package org.sleepwell.app;
import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.provider.Settings;import android.Manifest;
final class PictureCameraAccess {static final int REQUEST=787;enum Status{READY,NEEDED,SETTINGS,UNSUPPORTED}interface Port{Status status(Activity activity);void request(Activity activity);}static Port port=new Port(){public Status status(Activity a){if(!a.getPackageManager().hasSystemFeature(PackageManager.FEATURE_CAMERA_ANY))return Status.UNSUPPORTED;if(a.checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)return Status.READY;return !Prefs.flag(a,"pictureCameraAsked")||a.shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)?Status.NEEDED:Status.SETTINGS;}public void request(Activity a){Status state=status(a);if(state==Status.UNSUPPORTED)throw new IllegalStateException("No supported camera is available.");if(state==Status.READY)return;if(state==Status.SETTINGS){a.startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.getPackageName())));return;}Prefs.put(a,"pictureCameraAsked",true);a.requestPermissions(new String[]{Manifest.permission.CAMERA},REQUEST);}};private PictureCameraAccess(){}}
